# First, let me request demos and then load grids to understand the task
action = {"action": "request_demos"}
print(action)

# Load grids from the current session - this will show demo pairs we have for this task
import os, glob, re

def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    session_name = os.path.basename(session_dir)
    if not session_name:
        return {}

    # The jsonl file is in sessions folder under the instance's parent
    jsonl_path = os.path.join(session_dir, '..', '..', 'sessions', session_name + '.jsonl')
    print(f"Looking for jsonl at: {jsonl_path}")

    if os.path.exists(jsonl_path):
        with open(jsonl_path, 'r') as f:
            content = f.read()

        grids = {}
        # Find demo inputs/outputs
        for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, w, h = match.group(1), int(match.group(2)), int(match.group(3))
            grid_text = '\n'.join(content[match.end():].split('\n')[:h])
            rows = grid_text.split('\n')
            grid = [[int(x) for x in row.split()] for row in rows if row.strip()]
            grids[k] = grid

        return grids
    return {}

grids = load_grids()
print("Loaded grids:", list(grids.keys()))
for k, g in grids.items():
    print(f"{k} ({len(g)}x{len(g[0]) if g else 0}):")
    for row in g:
        print(" ".join(map(str, row)))

# Request demo pairs again
action = {"action": "request_demos"}
print(action)

# Reload and check grids
import os, glob, re

def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    session_name = os.path.basename(session_dir)

    if not session_name:
        return {}

    jsonl_path = os.path.join(session_dir, '..', '..', 'sessions', session_name + '.jsonl')

    if os.path.exists(jsonl_path):
        with open(jsonl_path, 'r') as f:
            content = f.read()

        grids = {}
        for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, w, h = match.group(1), int(match.group(2)), int(match.group(3))
            grid_text = '\n'.join(content[match.end():].split('\n')[:h])
            rows = grid_text.split('\n')
            valid_rows = [row for row in rows if row.strip()]
            if valid_rows:
                grid = [[int(x) for x in row.split()] for row in valid_rows]
                grids[k] = grid

        return grids
    return {}

grids = load_grids()
print("Grid keys:", list(grids.keys()))
for k, g in grids.items():
    print(f"\n{k} ({len(g)}x{len(g[0]) if g else 0}):")
    for row in g:
        print(" ".join(map(str, row)))

